"""Audit: functions whose nested-depth>=2 code objects reference module globals
that deconstruct_function's depth-1 harvest would miss."""
import importlib, inspect, pkgutil, types
import tinygrad

def names_at_depth(code, depth=0):
  out = {}
  for n in code.co_names: out.setdefault(n, depth)
  for c in code.co_consts:
    if isinstance(c, types.CodeType):
      for n, d in names_at_depth(c, depth+1).items():
        if n not in out or d < out[n]: out[n] = d
  return out

hits = []
for m in pkgutil.walk_packages(tinygrad.__path__, "tinygrad."):
  try: mod = importlib.import_module(m.name)
  except Exception: continue
  for fname, f in inspect.getmembers(mod, inspect.isfunction):
    if getattr(f, "__module__", None) != m.name: continue
    try: nd = names_at_depth(f.__code__)
    except Exception: continue
    deep_only = {n for n, d in nd.items() if d >= 2}
    shallow = {n for n, d in nd.items() if d <= 1}
    missing = {n for n in deep_only - shallow if n in f.__globals__ and not hasattr(__builtins__, n)}
    if missing: hits.append((m.name, fname, sorted(missing)))
for h in sorted(set(map(str, hits))): print(h)
EOF

uv run python - <<'EOF'
"""Audit ACTUAL PatternMatcher callbacks for depth>=2-only global refs."""
import importlib, inspect, pkgutil, types
import tinygrad
from tinygrad.uop.ops import PatternMatcher

def names_at_depth(code, depth=0):
  out = {}
  for n in code.co_names: out.setdefault(n, depth)
  for c in code.co_consts:
    if isinstance(c, types.CodeType):
      for n, d in names_at_depth(c, depth+1).items():
        if n not in out or d < out[n]: out[n] = d
  return out

import builtins
seen, hits = set(), []
for m in pkgutil.walk_packages(tinygrad.__path__, "tinygrad."):
  try: mod = importlib.import_module(m.name)
  except Exception: continue
  for pmname, pm in inspect.getmembers(mod, lambda o: isinstance(o, PatternMatcher)):
    for pat, fxn in getattr(pm, "patterns", []):
      if not callable(fxn) or fxn in seen: continue
      seen.add(fxn)
      try: nd = names_at_depth(fxn.__code__)
      except Exception: continue
      deep_only = {n for n, d in nd.items() if d >= 2} - {n for n, d in nd.items() if d <= 1}
      missing = {n for n in deep_only if n in fxn.__globals__ and not hasattr(builtins, n)}
      if missing: hits.append((m.name, pmname, getattr(fxn, "__name__", "?"), sorted(missing)))
for h in sorted(set(map(str, hits))): print(h)
print(f"\naudited {len(seen)} unique callbacks")
EOF

